// Verus program for the "disconnected corners" check.
//
// We only depend on the four corner arrows:
// horizontal[0], horizontal[n-1], vertical[0], vertical[m-1].
//
// Return convention:
// - disconnected => ['N','O','\n']
// - connected    => ['Y','E','S','\n']

#![allow(unused_imports)]
use vstd::prelude::*;

